/**
 * resource-pool.ts —— 跨项目资源池引擎（纯函数）
 *
 * 聚合多项目的任务数据，统计每个成员的跨项目负载、检测资源冲突。
 * 零副作用，纯输入输出。
 */
export interface PoolTaskInput {
    id: string;
    assigneeId?: string;
    status: 'todo' | 'in_progress' | 'blocked' | 'done' | 'cancelled';
    estimatedHours: number;
    dueAt?: Date;
    priority: 'low' | 'medium' | 'high' | 'urgent';
    projectId: string;
    projectName: string;
    isCritical?: boolean;
}
export interface MemberCapacity {
    id: string;
    name?: string;
    capacityHoursPerWeek?: number;
}
export interface MemberProjectLoad {
    projectId: string;
    projectName: string;
    hours: number;
    taskCount: number;
    inProgressCount: number;
}
export interface ResourceMember {
    assigneeId: string;
    name?: string;
    projects: MemberProjectLoad[];
    totalHours: number;
    capacityHours: number;
    utilization: number;
    loadLevel: 'idle' | 'normal' | 'heavy' | 'overload';
    inProgressCount: number;
    todoCount: number;
    dueSoonCount: number;
    criticalTaskCount: number;
}
export interface ResourceConflict {
    id: string;
    type: 'cross_project_overload' | 'same_deadline_contention' | 'critical_shared_task';
    severity: 'low' | 'medium' | 'high' | 'critical';
    title: string;
    description: string;
    assigneeId: string;
    assigneeName?: string;
    relatedProjectIds: string[];
    relatedTaskIds: string[];
    metric?: {
        name: string;
        value: number;
        threshold: number;
        unit: string;
    };
}
export interface ResourcePoolResult {
    members: ResourceMember[];
    totalCapacity: number;
    totalAllocated: number;
    utilization: number;
    overloadCount: number;
    idleCount: number;
    topBottlenecks: string[];
    conflicts: ResourceConflict[];
}
export declare function calculateResourcePool(tasks: PoolTaskInput[], members?: MemberCapacity[], now?: Date): ResourcePoolResult;
export interface RebalanceAction {
    id: string;
    actionType: 'reassign' | 'split_work' | 'defer_low_priority' | 'hire_support';
    title: string;
    rationale: string;
    fromAssigneeId?: string;
    toAssigneeId?: string;
    relatedTaskIds: string[];
    estimatedHoursReduction?: number;
    impact: string;
}
export interface RebalanceSuggestion {
    actions: RebalanceAction[];
    overloadedMembers: number;
    idleMembers: number;
    utilizationBefore: number;
    utilizationAfterEstimate: number;
    summary: string;
}
/**
 * 生成再平衡建议（确定性规则）
 * 规则：
 *  1. 过载 → 空闲：优先把低优任务迁移给空闲成员
 *  2. 过载 → 重载：如果无空闲，建议拆分大任务
 *  3. 高优临期多：建议延后低优先级任务
 *  4. 整体过载 > 80% 且无闲置：建议新增支持
 */
export declare function generateRebalanceSuggestions(tasks: PoolTaskInput[], members?: MemberCapacity[], now?: Date): RebalanceSuggestion;
